#include "vtf_block_decode.h"
#include <fstream>
#include <iostream>
std::vector<uint8_t>fixture(uint32_t format){std::vector<uint8_t>b(format==15?96:88);auto put=[&](size_t o,uint32_t v){std::memcpy(b.data()+o,&v,4);};auto half=[&](size_t o,uint16_t v){std::memcpy(b.data()+o,&v,2);};put(0,0x00465456);put(4,7);put(8,2);put(12,80);half(16,4);half(18,4);half(24,1);half(63,1);put(52,format);b[56]=1;return b;}
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");auto bc1=fixture(13);uint16_t red=0xf800,blue=0x001f;std::memcpy(bc1.data()+80,&red,2);std::memcpy(bc1.data()+82,&blue,2);bc1[84]=0xe4;auto a=decodeVtfMipCandidate(bc1,0);std::array<std::array<uint8_t,4>,4>expected{{{255,0,0,255},{0,0,255,255},{170,0,85,255},{85,0,170,255}}};for(size_t n=0;n<4;++n)if(std::memcmp(a.rgba.data()+n*4,expected[n].data(),4))throw std::runtime_error("BC1 interpolation");std::memcpy(bc1.data()+80,&blue,2);std::memcpy(bc1.data()+82,&red,2);if(decodeVtfMipCandidate(bc1,0).rgba[15]!=0)throw std::runtime_error("BC1 transparent branch");
 auto bc3=fixture(15);bc3[80]=0;bc3[81]=255;uint64_t selectors=6|(uint64_t(7)<<3)|(uint64_t(2)<<6);for(size_t n=0;n<6;++n)bc3[82+n]=uint8_t(selectors>>(n*8));std::memcpy(bc3.data()+88,&blue,2);std::memcpy(bc3.data()+90,&red,2);auto c=decodeVtfMipCandidate(bc3,0);if(c.rgba[3]!=0||c.rgba[7]!=255||c.rgba[11]!=51)throw std::runtime_error("BC3 six-alpha branch");bc3[80]=255;bc3[81]=0;auto d=decodeVtfMipCandidate(bc3,0);if(d.rgba[11]!=218)throw std::runtime_error("BC3 eight-alpha branch");
 if(argc!=3)throw std::runtime_error("installed texture output RGBA required");std::ifstream f(argv[1],std::ios::binary);if(!f)throw std::runtime_error("texture missing");std::vector<uint8_t>real((std::istreambuf_iterator<char>(f)),{});auto image=decodeVtfMipCandidate(real,2);std::ofstream out(argv[2],std::ios::binary);out.write(reinterpret_cast<const char*>(image.rgba.data()),std::streamsize(image.rgba.size()));out.close();if(!out)throw std::runtime_error("write image");std::cout<<"x64 DXT1/DXT5 decode branches passed real_mip="<<image.width<<'x'<<image.height<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
